def spec(
    card_id,
    module,
    kind,
    skill,
    section,
    title,
    content,
    example,
    pitfall,
    *,
    tags=(),
    applicable="题干或材料出现本卡对应任务时。",
    not_applicable="题干对象、范围或文种与本卡前提不一致时。",
):
    return {
        "id": card_id,
        "module": module,
        "kind": kind,
        "skill": skill,
        "section": section,
        "title": title,
        "content": content,
        "example": example,
        "pitfall": pitfall,
        "tags": list(tags) or [section, skill],
        "applicable": applicable,
        "not_applicable": not_applicable,
    }


