def build_cards():
    cards = []
    for item in SPECS:
        card = finalize_card(
            {
                "schema_version": "knowledge-card-v2",
                "id": item["id"],
                "title": item["title"],
                "module": item["module"],
                "kind": item["kind"],
                "skill": item["skill"],
                "difficulty": 2,
                "tags": item["tags"],
                "content": item["content"],
                "examples": [item["example"]],
                "counterexamples": [f"反例：{item['pitfall']}"],
                "pitfalls": [item["pitfall"]],
                "applicable_when": [item["applicable"]],
                "not_applicable_when": [item["not_applicable"]],
                "source": {
                    "name": "SaDuck 公考知识库",
                    "section": item["section"],
                    "license": "source-attributed-paraphrase",
                    "visibility": "public",
                },
                "review": {
                    "status": "reviewed",
                    "reviewer": "codex-domain-review-2026-07-16",
                    "reviewed_at": REVIEW_DATE,
                    "notes": "逐节改写指定七页的方法知识；不收录其后的作文模板、规范词、名言、人物素材和范文页。",
                },
                "version": 2,
            }
        )
        cards.append(card)
    return cards


def main():
    cards = build_cards()
    payload = "\n".join(json.dumps(card, ensure_ascii=False, separators=(",", ":")) for card in cards) + "\n"
    OUTPUT.write_text(payload, encoding="utf-8")
    print(f"wrote {len(cards)} cards to {OUTPUT}")


if __name__ == "__main__":
    main()
